LAYER
    NAME "flood_extent_rp25"
    TYPE RASTER
    STATUS ON
    DATA "data/return_periods/M6_25y_clipped.tif"
    MASK "gha_admin_extent_mask"
    PROCESSING "NODATA=0"
    INCLUDE "shared/common-layer-properties.map"
    TYPE RASTER
    INCLUDE "classifications/flood-extent-rp25.classes.map"
    METADATA
        "wms_title" "Flood Extent / Hazard - 25 Year Return Period"
        "wms_abstract" "Aggregated fluvial flood hazard model-consensus raster (1-in-25 years)"
        INCLUDE "shared/wms-layer-metadata.map"
    END
END

